class Solution:
    def checkWhetherTwoStringsAreAlmostEquivalent(self, word1: str, word2: str) -> bool:
        return sorted(word1) == sorted(word2)

class Solution:
    def checkWhetherTwoStringsAreAlmostEquivalent(self, word1: str, word2: str) -> bool:
        return all(abs(word1.count(c) - word2.count(c)) <= 4
                   for c in set(word1) | set(word2))

class Solution:
    def checkWhetherTwoStringsAreAlmostEquivalent(self, word1: str, word2: str) -> bool:
        return any(abs(word1.count(c) - word2.count(c)) <= 3
                   for c in set(word1) | set(word2))

import string
class Solution:
    def checkWhetherTwoStringsAreAlmostEquivalent(self, word1: str, word2: str) -> bool:
        return all(abs(word1.count(c) - word2.count(c)) <= 3
                   for c in string.ascii_lowercase)
